import{_ as o,C as r,c as n,o as d,a3 as e,G as i}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Trial balance","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/reporting/trial-balance.md","filePath":"master/finance/reporting/trial-balance.md","lastUpdated":1793074831000}'),s={name:"master/finance/reporting/trial-balance.md"};function l(h,t,c,g,p,u){const a=r("ImagePopup");return d(),n("div",null,[t[0]||(t[0]=e('<h1 id="trial-balance" tabindex="-1">Trial balance <a class="header-anchor" href="#trial-balance" aria-label="Permalink to &quot;Trial balance&quot;">​</a></h1><p>The trial balance lists every account with its debit and credit totals. The grand totals of debit and credit must be equal. Use it to check that your books are balanced before you produce the final statements.</p><blockquote><p><strong>In simple words:</strong> The trial balance is a quick health check. If total debit equals total credit, the books add up.</p></blockquote><p>It is in the Accounting app only: <code>Accounting → Reporting → Trial Balance</code>.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2>',5)),i(a,{src:"/images1/finance/trial_balance.png",alt:"Trial Balance with Date Range This Month (01/10/2026 - 31/10/2026) showing Initial Balance, the period and End Balance column groups"}),t[1]||(t[1]=e('<ul><li><strong><em>Date Range:</em></strong> The period in the middle column group.</li><li><strong><em>Journals:</em></strong> Limit the report to chosen journals.</li></ul><h2 id="how-to-read-it" tabindex="-1">How to read it <a class="header-anchor" href="#how-to-read-it" aria-label="Permalink to &quot;How to read it&quot;">​</a></h2><p>The report has three column groups. Each group has a <strong>Debit</strong> and a <strong>Credit</strong> column.</p><ul><li><strong>INITIAL BALANCE:</strong> The totals of everything posted before the start of the range.</li><li><strong>The period</strong> (for example <strong>01 OCT 2026 - 31 OCT 2026</strong>): The movements inside the range.</li><li><strong>END BALANCE:</strong> Initial balance plus the period.</li></ul><p>Example with the range October 2026. All sample entries are from July, so they sit in the initial balance and the period is zero.</p><table tabindex="0"><thead><tr><th>Account</th><th>Initial Debit</th><th>Initial Credit</th><th>End Debit</th><th>End Credit</th></tr></thead><tbody><tr><td>101403 Outstanding Receipts</td><td>891.25</td><td>0.00</td><td>891.25</td><td>0.00</td></tr><tr><td>101404 Outstanding Payments</td><td>0.00</td><td>34,040.00</td><td>0.00</td><td>34,040.00</td></tr><tr><td>121000 Account Receivable</td><td>2,098.75</td><td>891.25</td><td>2,098.75</td><td>891.25</td></tr><tr><td>131000 Tax Paid</td><td>4,440.00</td><td>0.00</td><td>4,440.00</td><td>0.00</td></tr><tr><td>211000 Account Payable</td><td>34,040.00</td><td>34,040.00</td><td>34,040.00</td><td>34,040.00</td></tr><tr><td>251000 Tax Received</td><td>0.00</td><td>273.75</td><td>0.00</td><td>273.75</td></tr><tr><td>400000 Product Sales</td><td>0.00</td><td>1,825.00</td><td>0.00</td><td>1,825.00</td></tr><tr><td>600000 Expenses</td><td>29,600.00</td><td>0.00</td><td>29,600.00</td><td>0.00</td></tr><tr><td><strong>Total</strong></td><td><strong>71,070.00</strong></td><td><strong>71,070.00</strong></td><td><strong>71,070.00</strong></td><td><strong>71,070.00</strong></td></tr></tbody></table><p>The <strong>Total</strong> row shows 71,070.00 on both sides. The books are balanced.</p><p>Look at <strong>Account Payable</strong>. It has 34,040.00 in debit and in credit. The bill raised the credit and the payment raised the debit, so the account is settled.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Click <strong>Export to Excel</strong> or <strong>Export to PDF</strong> to download the report.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>What if the totals differ?</strong> A posted entry is out of balance. Open <a href="./../accounting-entries/journal-items.html">Journal items</a> and look for the entry whose <strong>Debit</strong> and <strong>Credit</strong> differ.</p><p><strong>Why do I see my July amounts in the Initial Balance?</strong> The initial balance holds everything before the range. Pick a range that includes July to see the movements.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./general-ledger.html">General ledger</a></li><li><a href="./balance-sheet.html">Balance sheet</a></li><li><a href="./../accounting-entries/journal-entries.html">Journal entries</a></li></ul>',15))])}const f=o(s,[["render",l]]);export{b as __pageData,f as default};
